   ```javascript
   Java.perform(function () {
     var cls = Java.use("[包名].LicenseManager");
     cls.checkResponse.overload('java.lang.String').implementation = function (s) {
       console.log("[resp] " + s);
       return this.checkResponse(s);
     };
   });
